    WHERE pw.word_id = '4501600101' AND p.language_id = (SELECT id FROM language WHERE code = 'hin') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '4501600101' FROM np ON CONFLICT DO NOTHING;
